---------------------------------------------------------------
--	静止帧参数
    
--	静止帧播放速度的贝塞尔曲线
--       /\ 
--        | 播放速度
-- 2-Smin-|------------------->  _--:--_
--        |                     /        \
--        |                    /          \
--        |                  _/            \_
--    1.0-:_-------------_ :-----------------:------
--        | \           /
--        |  \         /
--        |   \       /
--  Smin -|____-__:__-_____:________:________:_____>时间
--        0      (t)     (2t)     (3t)     (4t)
--

--技能参数判定
--1、所有技能判定出招时间和收招时间加起来大于1秒的有100ms的静止帧，大于1.5秒的有150ms静止帧；
--2、所有位移技能如果倾向于只穿越攻击一个人的，填100ms静止帧，如果穿越多个人的，填75ms静止帧；
--3、所有明显的击飞、击倒、击退技能，增加100ms静止帧。


--静止帧参数说明
--1、序号是判定所在段的段ID；
--2、第一个参数一般填2或者0，有效则填2，无效则填0；
--3、第二个参数一般填0；
--4、第三个参数就是静止帧时间，毫秒单位；
--5、第四个参数一般填1.



--
FrozenFrameID =
{
	FROZENFRAME_INVALID	= 0,
	FROZENFRAME_SHORT	= 1,
	FROZENFRAME_MID		= 2,
	FROZENFRAME_LONG	= 3,
}

FrozenFrameParam =
{
	[FrozenFrameID.FROZENFRAME_INVALID] =
	{
		0,		--	是否有效。0：无效，1：有效，2：只有静止段无恢复段, 3: 全静止，4t时间后切到对应时间播
		0.0,		--	播放速度最小值，即上图的Smin。范围：[-0.5, 2.0]
					--	如果写为负数，曲线会下拉（但实际速度<0会切为0）
		0,			--	达到最小速度的时间（毫秒），即上图的t。范围：[50, 300]
		0.0,		--	曲线底部的弯曲度，越大底部越宽，越小底部越尖。范围：[0.1, 1.0]
	},

	[FrozenFrameID.FROZENFRAME_SHORT] =
	{
		0,		--	是否有效。0：无效，1：有效，2：只有静止段无恢复段, 3: 全静止，4t时间后切到对应时间播
		0,		--	播放速度最小值，即上图的Smin。范围：[-0.5, 2.0]
					--	如果写为负数，曲线会下拉（但实际速度<0会切为0）
		50,			--	达到最小速度的时间（毫秒），即上图的t。范围：[50, 300]
		0.8,		--	曲线底部的弯曲度，越大底部越宽，越小底部越尖。范围：[0.1, 1.0]
	},

	[FrozenFrameID.FROZENFRAME_MID] =
	{
		0,		--	是否有效。0：无效，1：有效，2：只有静止段无恢复段, 3: 全静止，4t时间后切到对应时间播
		0.1,		--	播放速度最小值，即上图的Smin。范围：[-0.5, 2.0]
					--	如果写为负数，曲线会下拉（但实际速度<0会切为0）
		75,			--	达到最小速度的时间（毫秒），即上图的t。范围：[50, 300]
		0.5,		--	曲线底部的弯曲度，越大底部越宽，越小底部越尖。范围：[0.1, 1.0]
	},
	
	[FrozenFrameID.FROZENFRAME_LONG] =
	{
		0,		--	是否有效。0：无效，1：有效，2：只有静止段无恢复段, 3: 全静止，4t时间后切到对应时间播
		0.2,		--	播放速度最小值，即上图的Smin。范围：[-0.5, 2.0]
					--	如果写为负数，曲线会下拉（但实际速度<0会切为0）
		100,		--	达到最小速度的时间（毫秒），即上图的t。范围：[50, 300]
		0.3,		--	曲线底部的弯曲度，越大底部越宽，越小底部越尖。范围：[0.1, 1.0]
