-----------------------------------------------------
--	取所有受伤表现参数
-----------------------------------------------------
-- tidVictim: 受伤者的模板id（NPC/怪才有，人==0）
-- idAtkPerform: 攻击的PerformID
-- nPerformTime: 攻击Perform的时间（ms）
-- fDamage: 伤害值
-- fCurHPPercent：当前HP百分比
-- fDamagePercent：伤害导致的百分比变化
function DamageVisual:GetDamageVisualParam(tidVictim, idAtkPerform, nPerformTime, nProf, fDamage, fCurHPPercent, fDamagePercent, bSubObjPerf)

	--	受伤高亮
	local damage_type = DamageVisualID.DAMAGE_0
	if fDamage > 100 or fDamagePercent > 0.1 then
		damage_type = DamageVisualID.DAMAGE_1
	end
	local glowparam = DamageGlowParam[damage_type]	

	--	静止帧
	local frozenparam = DamageVisual:GetFrozenParam(idAtkPerform, nPerformTime, nProf)
	if frozenparam == nil then
		frozenparam = FrozenFrameParam[FrozenFrameID.FROZENFRAME_INVALID]
	end

	--	受伤抖动（配置偏移的缩放比例上下限。实际偏移量根据伤血百分比和上下限计算）
	local tabQuiverScale = {DamageQuiverParam[2], DamageQuiverParam[3]}
	local tabMonCfg = MonsterVisual.BeAtkConfig[tidVictim]
	if tabMonCfg and tabMonCfg.canshake ~= true then
   	-- 都为0表示不能shake	
		tabQuiverScale[1] = 0
		tabQuiverScale[2] = 0
	else
		local tabQuiverScale1 = DamageQuiverScale[idAtkPerform]
		if tabQuiverScale1 then 	--	根据idAtkPerform取到抖动的参数. 都为0表示不能shake
			tabQuiverScale = tabQuiverScale1
		end
	end

	--	受伤动作、声音、打击光效配置
	local dmgTab = bSubObjPerf and SubObjPerfDmgCfg or DamageActGfxSoundCfg
	local actGfxSoundCfg = dmgTab[idAtkPerform]
	if actGfxSoundCfg == nil then
		actGfxSoundCfg = dmgTab["default"]
	end
	
	-- 	物理受伤参数
	local phyAtkCfg = PhyAtkPerformCfg["default"]
	if not bSubObjPerf then
		local phyAtkCfg_Perform = PhyAtkPerformCfg[idAtkPerform]
		if phyAtkCfg_Perform ~= nil then
			phyAtkCfg = phyAtkCfg_Perform
		end
	end
	--	根据tabMonCfg配置，改写phyAtkCfg
	if tabMonCfg then
		if tabMonCfg.canPhyDmg ~= nil then
			phyAtkCfg[1] = tabMonCfg.canPhyDmg
		end
	end	

	--local strdbg = string.format("PhyAtkCfg: tid %d, Perform %d, Enable: %d, PauseAnim: %d\n",
	--		tidVictim, idAtkPerform, phyAtkCfg[1] and 1 or 0, phyAtkCfg[2] and 1 or 0)
	--LogPrint(strdbg)

	return 	glowparam,	--	Glow参数
			frozenparam,		--	静止帧参数
			tabQuiverScale,	--	quiver参数
			actGfxSoundCfg,	--	受伤动作、光效等配置
			phyAtkCfg 			--	物理受伤参数配置
end

--	单取静止帧参数
function DamageVisual:GetFrozenParam(idAtkPerform, nPerformTime, nProf)

	local frozenparam = FrozenFrameParam[FrozenFrameID.FROZENFRAME_INVALID]
	local tabFrozenPerform = FrozenFramePerformDefine[idAtkPerform]
	if tabFrozenPerform then	--	根据idAtkPerform取到静止帧的参数
		frozenparam = tabFrozenPerform
	elseif nProf == 7 or nProf == 8 -- 五毒和逍遥：没有静止帧
		or nPerformTime < 700 then -- perform时间太短：没有静止帧
		frozenparam = FrozenFrameParam[FrozenFrameID.FROZENFRAME_INVALID]
	elseif nPerformTime < 1000 then
		frozenparam = FrozenFrameParam[FrozenFrameID.FROZENFRAME_SHORT]
		frozenparam[3] = nPerformTime * 0.25
	elseif nPerformTime < 1500 then
		frozenparam = FrozenFrameParam[FrozenFrameID.FROZENFRAME_MID]
	else
		frozenparam = FrozenFrameParam[FrozenFrameID.FROZENFRAME_LONG]
	end
	
	return frozenparam
end